const tabs=mainSections;
async function api(url,body){if(published&&body!==undefined&&!url.endsWith('/calculate'))throw Error('Alterações são feitas no acervo de trabalho Barch.');const r=await fetch(url,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json','X-Barch-Token':token},body:body===undefined?undefined:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error||d.diagnostics?.map(x=>x.message).join(' ')||'Não foi possível concluir.');return d;}
const endpoint=action=>`/terreno/api/studies/${study.slug}/${action}`;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),5500);}
function run(fn){return async e=>{try{await fn(e);}catch(error){toast(error.message);}};}
function destroy(){summaryController?.destroy();summaryController=null;advisoryCleanup?.();advisoryCleanup=null;economicCleanup?.();economicCleanup=null;fieldCleanup?.();fieldCleanup=null;destroySubdivisionCharts();destroyOperationalMarketCharts();if(streetViewHandle){const b=streetViewHandle.getState?.().panoramasOpened>0?streetViewHandle.getBookmark?.():null;if(b)streetBookmark={heading:b.heading,pitch:b.pitch,fov:b.fov};streetViewHandle.destroy();streetViewHandle=null;}map?.destroy();map=null;volumeView?.destroy();volumeView=null;for(const c of charts)c.destroy();charts=[];clearTimeout(timer);requestNumber++;}
function shell(){destroy();$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><img class="logo" src="/terreno/assets/barch.svg" alt="Barch"><div class="eyebrow">Inteligência territorial</div><select class="study-picker" aria-label="Selecionar terreno">${studies.map(s=>`<option value="${s.slug}" ${study.slug===s.slug?'selected':''}>${esc(s.title)}</option>`).join('')}</select><button id="new-study">+ Novo terreno</button><nav class="nav" aria-label="Seções do estudo">${tabs.map(([id,label],i)=>`<button data-tab="${id}" class="${id===parentSection(tab)?'active':''}" ${id===parentSection(tab)?'aria-current="page"':''}><span>${num(i+1).padStart(2,'0')}</span>${label}</button>`).join('')}</nav><details class="support-nav" ${supportPages.some(([id])=>id===tab)?'open':''}><summary>Dossiê e execução</summary><nav class="nav" aria-label="Ferramentas de apoio">${supportPages.map(([id,label])=>`<button data-tab="${id}" class="${id===tab?'active':''}" ${id===tab?'aria-current="page"':''}>${label}</button>`).join('')}</nav></details><div class="sidebar-bottom"><strong>Análise de áreas</strong>Área · valor · aquisição<div style="margin-top:12px">${concept?'Concept · uso e testes<br>Acervo documental selecionado':published?'Estudo publicado<br>Acervo documental selecionado':'Ambiente de trabalho local<br>Documentos de acesso interno'}</div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Barch / Áreas / <strong>${esc(study.municipality)}</strong></div><div class="top-actions">${badge(concept?'Concept · uso e testes':'Em qualificação',concept?'gray concept-badge':'green')}${published?'':'<button id="qualify-study">Qualificar cadastro</button>'}<button id="export-summary">Exportar resumo</button><button id="export">Dossiê JSON</button></div></header><div class="workspace"><header class="pagehead"><div><div class="eyebrow">${esc(study.subtitle)} · ${esc(study.parcel)}</div><h1>${esc(study.title)}</h1><p>${esc(study.address)} · Estudo de ${dt(study.asOf)}</p></div>${badge(study.stage)}</header><div class="advisory-engine-anchor" hidden>${renderAdvisoryStrip()}</div><div id="content"></div><footer class="footer"><span>Barch · Análise de áreas · ${esc(study.title)}</span><span>Hipóteses, evidências e decisões com rastreabilidade.</span></footer></div></main></div>`;
 $('.study-picker').addEventListener('change',run(e=>load(e.target.value)));
 $$('[data-tab]').forEach(b=>b.addEventListener('click',()=>{tab=b.dataset.tab;render();}));
 $('#qualify-study')?.addEventListener('click',run(()=>editQualification({study,api,openDialog,toast})));$('#new-study').addEventListener('click',run(newStudy));$('#export-summary').addEventListener('click',()=>{tab='summary';render();});$('#export').addEventListener('click',()=>window.open(endpoint('export'),'_blank','noopener'));}
async function load(slug){const loadRequest=++studyLoadSequence;summaryController?.pending('Carregando o terreno selecionado…');advisoryCleanup?.();advisoryCleanup=null;document.querySelectorAll('[data-tab],#export-summary,#export,[data-summary-export]').forEach(b=>b.disabled=true);streetViewHandle?.destroy();streetViewHandle=null;streetBookmark=null;let loaded;try{loaded=await api(`/terreno/api/studies/${slug}`);}catch(error){if(loadRequest!==studyLoadSequence)return;if(study)render();throw error;}if(loadRequest!==studyLoadSequence)return;study=loaded;activePreset=primaryPreset();changes={...(activePreset?.controls||{})};result=null;gps=null;volume={floors:study.principalProduct?.floors||8,floorHeightM:3};if(occupationChoices(study).length)study=selectOccupation(study,study.sitePotential.occupation.defaultId);history.replaceState(null,'',`?terreno=${encodeURIComponent(study.slug)}#${tab}`);render();}
function kpi(label,value,hint='',highlight=false){return `<div class="kpi ${highlight?'highlight':''}"><div class="label">${label}</div><strong class="${value==='Não demonstrado'||value==='A confirmar'?'value-missing':''}">${value}</strong><div class="hint">${hint}</div></div>`;}
function docPageLinks(page){const doc=study.documents.find(d=>d.type==='laudo-avaliacao');if(!doc)return '';return [...new Set(Array.isArray(page)?page:[page])].filter(Number.isInteger).map(p=>`<a href="${endpoint('documents')}/${doc.id}#page=${p}" data-doc-page="${p}" data-document="${doc.id}" target="_blank" rel="noopener">p. ${p}</a>`).join(' · ');}
function checkRows(){const surroundings=summarizeSurroundings(study.surroundings);return study.checks.map(c=>`<div class="check"><h3>${esc(c.axis)}${c.page?`<br>${docPageLinks(c.page)}`:''}</h3><div><p>${esc(c.finding)}</p><p class="action">${esc(c.action)}</p></div>${badge(c.status)}</div>`).join('')+surroundings.items.map(o=>`<div class="check"><h3>Entorno · ${esc(o.label)}</h3><div><p>${esc(o.note)}</p>${o.nextAction?`<p class="action">${esc(o.nextAction)}</p>`:''}<p class="tiny muted">${esc(o.responsible)} · ${dt(o.reviewedOn)} · <a href="#field">Conferir origem e evidências na vistoria</a></p></div>${badge({'a-verificar':'A verificar',indicio:'Indício a investigar','evidencia-referenciada':'Evidência vinculada','nao-aplicavel':'Não aplicável'}[o.status])}</div>`).join('');}
function opportunity(){return study.opportunities?.length?`<section class="section-gap"><div class="row between"><div><h2 class="section-title">Possibilidades a aprofundar</h2><p class="small muted">Explorações posteriores à análise principal. Cada hipótese tem uma condição de descarte.</p></div>${badge('Exploratório')}</div><div class="grid three">${study.opportunities.map(o=>`<article class="card opportunity"><h3>${esc(o.title)}</h3><p>${esc(o.condition)}</p><p class="kill"><strong>Descartar se:</strong> ${esc(o.kill)}</p></article>`).join('')}</div></section>`:'';}
function chart(id,options){const old=charts.filter(c=>c._barchContainer===id);for(const c of old)c.destroy();charts=charts.filter(c=>c._barchContainer!==id);const el=document.getElementById(id);if(!el||!window.ApexCharts)return;const c=new window.ApexCharts(el,{colors:['#9C745B','#57705C','#B8AB82','#A2B3BA'],dataLabels:{enabled:false},grid:{borderColor:'#ebe9e1',strokeDashArray:3},tooltip:{theme:'light'},legend:{fontSize:'11px',position:'bottom'},stroke:{width:2.5},...options,chart:{fontFamily:'Inter, Arial, sans-serif',toolbar:{show:false},animations:{enabled:false},height:285,background:'transparent',...options.chart}});c._barchContainer=id;charts.push(c);c._barchReady=c.render();return c;}
function primaryPreset(){return study?.presets?.find(p=>p.id===study.principalProduct?.presetId)||study?.presets?.find(p=>p.id===study.presetIds?.[0])||study?.presets?.[0]||null;}
function principalChanges(){const p=primaryPreset();return activePreset?.id===p?.id?{...changes}:{...(p?.controls||{})};}
function productLabel(){return study.principalProduct?.label||primaryPreset()?.label||'Produto a qualificar';}
async function drawMap(){if(!$('#map'))return;const slug=study.slug,container=$('#map');try{const mounted=await mountMap(container,study,{mode:'2d',showVolumes:false});if(study.slug!==slug||container!==$('#map'))mounted?.destroy();else {map=mounted;for(const el of $$('[data-layer-group]'))for(const id of el.dataset.layerGroup.split(','))map?.setLayer(id,el.checked);$('#fit-map').disabled=false;if($('#terrain-dem'))$('#terrain-dem').disabled=false;}}catch(e){if(container===$('#map'))container.innerHTML=`<div class="empty"><h3>Cartografia indisponível</h3><p>${esc(e.message)}</p></div>`;}}
async function drawVolume(){const container=$('#volume');if(!container)return;const slug=study.slug;try{const renderer=container.dataset.context==='google'?mountGoogleScene:mountVolume;const mounted=await renderer(container,study,{...volume,productLabel:productLabel(),view:'iso',physicalOnly:container.dataset.physicalOnly==='true'});if(study.slug!==slug||container!==$('#volume'))mounted?.destroy();else{volumeView=mounted;volumeView?.setScenario?.({floors:volume.floors});if($('#existing-buildings')?.checked)volumeView?.setExistingBuildings?.(true);$('#fit-volume')?.removeAttribute('disabled');}}catch(e){if(container===$('#volume'))container.innerHTML=`<div class="empty"><h3>Volumetria a qualificar</h3><p>${esc(e.message)}</p></div>`;}}
function volumePanel(hero=false,physical=false){if(physical)return `<section class="card volume-card hero-volume"><header class="card-head"><div class="row between wrap"><div><div class="eyebrow">Área · contexto físico</div><h2 class="section-title">Terreno e entorno em 3D</h2></div><div class="row"><select id="volume-view" aria-label="Vista do terreno"><option value="iso">Isométrica</option><option value="top">Vista superior</option><option value="front">Frontal</option></select><button id="fit-volume" disabled>Enquadrar</button></div></div></header><div id="volume" class="volume-canvas google-context" data-context="google" data-physical-only="true"></div></section>`;return `<section class="card volume-card ${hero?'hero-volume':''}"><header class="card-head"><div class="row between wrap"><div><div class="eyebrow">Potencial de uso · ${esc(productLabel())}</div><h2 class="section-title">${(study.regulatory||study.geography?.exploratoryProposal)?(hero?'Terreno, proposta e entorno em 3D':'Envelope e implantação em 3D'):(hero?'Terreno e entorno em 3D':'Terreno em 3D')}</h2></div><div class="row">${hero&&study.geography?.layers?.some(l=>l.id==='volumes'&&l.status==='available')?'<label class="existing-toggle"><input id="existing-buildings" type="checkbox"> Ocupação atual</label>':''}<select id="volume-view" aria-label="Vista da volumetria"><option value="iso">Isométrica</option><option value="top">Implantação</option><option value="front">Elevação</option></select><button id="fit-volume" disabled aria-label="Enquadrar volumetria">Enquadrar</button></div></div></header><div id="volume" class="volume-canvas ${hero||study.subdivisionReview?'google-context':''}" data-context="${hero||study.subdivisionReview?'google':'geometry'}"></div>${occupationSelector(study)}${study.regulatory?physicalControls():study.geography?.exploratoryProposal?exploratoryControls():`<div class="map-footer">${study.geography.parcelUrl?'Fonte e condicionantes disponíveis na análise territorial.':study.localShape?'Planta local do documento disponível para conciliação.':'Cadastre o perímetro para explorar o terreno.'}</div>`}</section>`;}
function bindVolume(){drawVolume();if($('#occupation-choice'))$('#occupation-choice').onchange=e=>{study=selectOccupation(study,e.target.value);render();};$('#volume-view').onchange=e=>volumeView?.setView(e.target.value);$('#fit-volume').onclick=()=>volumeView?.fit();if($('#existing-buildings'))$('#existing-buildings').onchange=e=>volumeView?.setExistingBuildings?.(e.target.checked);if($('#volume')?.dataset.physicalOnly!=='true'){if(study.geography?.exploratoryProposal&&!study.regulatory)initExploratoryControls();else initPhysicalControls();}}

function sectionFrame(){const pages=sectionPages[parentSection(tab)];if(!pages)return;const active=tab==='scenarios'?'business':tab;$('#content').insertAdjacentHTML('afterbegin',`<nav class="section-subnav" aria-label="${parentSection(tab)==='asset'?'Análise do terreno':'Potencial de uso e negócio'}">${pages.map(([id,label])=>`<button data-section-page="${id}" class="${id===active?'active':''}" ${id===active?'aria-current="page"':''}>${label}</button>`).join('')}</nav>`);$$('[data-section-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.sectionPage));}
function render(){const edition=++renderSequence;shell();const host=$('#content');history.replaceState(null,'',`?terreno=${encodeURIComponent(study.slug)}#${tab}`);const task=({overview,asset,business,landvalue,territory,economics,scenarios,market,diligence,documents,field,method,summary}[tab]||overview)();if(task?.then)task.then(()=>{if(edition===renderSequence&&host===$('#content'))sectionFrame();});else sectionFrame();advisoryCleanup=bindAdvisory(study,{api,esc,chart,onNavigate:navigate,toast,onResult:r=>{if(tab==='overview')paintDiagnosis(study,r,{onNavigate:navigate});if(tab==='landvalue')paintLandValue(study,r,{chart,onNavigate:navigate});summaryController?.update(r);},onPending:message=>{pendingDiagnosis(message);summaryController?.pending(message);}});}

function navigate(id){tab=id;render();}
function landvalue(){$('#content').innerHTML=renderLandValue();}
function summary(){$('#content').innerHTML=renderDashboardSummary();summaryController=bindDashboardSummary(study,{chart,onNavigate:navigate,toast});}
function marketPreview(){const m=study.qualifiedMarket;if(!m)return renderOperationalMarketPreview(study);return `<section class="card card-body section-gap market-overview"><div class="row between wrap"><div><div class="eyebrow">Referências do produto e do terreno</div><h2 class="section-title">${num(m.products.length)} benchmarks para confrontar a tese</h2></div><button id="go-market">Conferir referências de mercado</button></div><div class="grid three section-gap">${m.products.filter(p=>['condessa','oasis','orbita'].includes(p.id)).map(p=>`<div><strong>${esc(p.name)}</strong><p class="small">${esc(p.segment)}</p><p class="small">${num(p.areaMin,2)}${p.areaMin!==p.areaMax?'–'+num(p.areaMax,2):''} m² · ${p.ticket?money(p.ticket):'Referência de implantação'}</p><span class="tiny muted">${esc(p.fit)}</span></div>`).join('')}</div><p class="small muted">Terrenos: ${num(m.landOffers.filter(x=>x.status!=='excluido').length)} ofertas de contexto e ${num(m.landTransactions.length)} transações fiscais selecionadas. A diferença de porte e benfeitorias exige avaliação própria.</p></section>`;}
function potentialNavigation(){bindSitePotential(study,{chart,onSelect:id=>{study=selectOccupation(study,id);tab='territory';render();},onTerritory:()=>{tab='territory';render();}});}
