function asset(){const s=study,land=s.landEconomics?.value?.subject;$('#content').innerHTML=`<section class="card card-body"><div class="eyebrow">Área · identidade, contexto e valor</div><div class="row between wrap"><div><h2 class="section-title">Caracterização do terreno</h2><p class="small muted">${esc(s.address)} · ${esc(s.municipality)} / ${esc(s.uf)}</p></div><button data-asset-nav="landvalue">Conferir preço da terra →</button></div><div class="asset-facts">${[['Área de referência',s.areaM2==null?'A qualificar':num(s.areaM2,2)+' m²',s.subdivisionReview?'Área bruta informada no projeto':s.siteReview?.areas?.registryM2!=null?'Área registral informada':s.regulatory?'Área fiscal indicada no estudo':'Base documental indicada no estudo'],['Identificação',s.parcel||'A qualificar','Vincular matrícula, cadastro e perímetro'],['Enquadramento',({urbano:'Urbano',rural:'Rural',transicao:'Transição urbano/rural'}[s.landContext]||land?.regime||'A qualificar'),'Confrontar cadastro urbano/rural e legislação'],['Zona indicada',s.regulatory?.zone||s.siteReview?.urbanism?.zone||s.zone||'A qualificar','Vigência e incidência constam nas diligências']].map(([label,value,note])=>`<article class="card"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(note)}</small></article>`).join('')}</div><div class="row wrap"><button data-asset-nav="documents">Documentos da área</button><button data-asset-nav="diligence">Diligência completa</button><button id="go-streetview">Street View e vistoria</button></div></section><div class="territory-pair section-gap"><section class="card map-card"><header class="card-head"><div class="row between wrap"><div><h2 class="section-title">Terreno e camadas do território</h2><p>Perímetro, relevo e bases territoriais disponíveis.</p></div><button id="fit-map" disabled>Enquadrar</button></div>${layerMenu()}</header><div id="map" class="mapbox large"></div></section>${volumePanel(true,true)}</div>${renderAssetReadings(s)}${contextPanel()}${climatePanel(s,{esc,num})}<div class="section-gap">${renderDiligenceProtocol()}</div>`;drawMap();bindVolume();bindContext();bindClimate(s,{chart});bindDiligenceProtocol(s,{api,onNavigate:navigate});$$('[data-asset-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.assetNav));$('#go-streetview').onclick=openStreetView;$('#fit-map').onclick=()=>map?.fit();$$('[data-layer-group]').forEach(el=>el.onchange=()=>{if(el.id==='terrain-dem')map?.setTerrain(el.checked);for(const id of el.dataset.layerGroup.split(',').filter(Boolean))map?.setLayer(id,el.checked);});}
function renderAssetReadings(s){const rows=(s.checks??[]).filter(c=>/identidade|domínio|área|acesso|geometria|zoneamento|regime|água|solo|APP|aprovação|licenças|disponibilidade|vegetação/i.test(c.axis));return `<section class="card card-body section-gap"><div class="eyebrow">Leitura documental e territorial</div><h2 class="section-title">Caracterização registrada da área</h2><p class="small muted">Achados do dossiê e ações para validar incidência e efeito no valor.</p>${rows.map(c=>`<div class="check"><h3>${esc(c.axis)}</h3><div><p>${esc(c.finding)}</p><p class="action">${esc(c.action)}</p></div>${badge(c.status)}</div>`).join('')||'<p>Consolidar cadastro, poligonal, acessos e fontes municipais na pesquisa da área.</p>'}</section>`;}
function business(){scenarios();$('#content').insertAdjacentHTML('afterbegin',`<section class="card card-body"><div class="eyebrow">Depois de qualificar a área</div><h2 class="section-title">Potencial de uso e negócio</h2><p class="small muted">${esc(productLabel())} · explorar ocupação, limites físicos e econômicos. O estudo de produto será aprofundado no Wizard.</p><div class="row wrap"><button data-business-nav="territory">Envelope e implantação</button><button data-business-nav="market">Benchmarks do produto</button><button data-business-nav="economics">Modular aquisição e retorno</button></div></section>`);$$('[data-business-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.businessNav));}
function shape(){const v=study.localShape?.vertices;if(!v)return '';const xs=v.map(v=>v[0]),ys=v.map(v=>v[1]),xmin=Math.min(...xs),ymin=Math.min(...ys),dx=Math.max(...xs)-xmin,dy=Math.max(...ys)-ymin;const scale=Math.min(220/dx,225/dy);const pts=v.map(([x,y])=>`${150+(x-xmin-dx/2)*scale},${250-(y-ymin)*scale}`).join(' ');return `<svg viewBox="0 0 300 275" class="shape-svg" role="img" aria-label="Planta local dos sete vértices transcritos, sem adoção de coordenadas geográficas"><path d="M35 250H265M35 25V250" stroke="#e8e4d8" fill="none"/><polygon points="${pts}" fill="#d4ddcd" stroke="#60755d" stroke-width="2"/>${v.map(([x,y],i)=>`<circle cx="${150+(x-xmin-dx/2)*scale}" cy="${250-(y-ymin)*scale}" r="2.5" fill="#925f43"/><text x="${156+(x-xmin-dx/2)*scale}" y="${250-(y-ymin)*scale}" font-size="8" fill="#5a6251">${i+1}</text>`).join('')}<text x="37" y="265" font-size="9" fill="#8a867c">Planta em coordenadas locais · sem datum adotado</text></svg>`;}
function contextPanel(){
 const c=study.context,ind=c?.indicators||[],local=study.localContext,point=local?.sectors?.find(s=>s.containsReferencePoint),hasLocal=local?.status==='ok'&&local?.sectors?.length;
 return `<section class="card context-card section-gap"><header class="card-head"><div class="row between wrap"><div><div class="eyebrow">IBGE · Censo ${esc(local?.referenceYear||2022)}</div><h2 class="section-title">População e território</h2></div>${badge(hasLocal?'Entorno mapeado':c?.status==='ok'?'Município consultado':c?.status==='parcial'?'Cobertura parcial':'Consulta pendente','gray')}</div><p>Leitura demográfica em escalas distintas, para confrontar localização, público e produto.</p></header>${hasLocal?`<div class="context-local-head"><div><span class="label">Setor que contém o ponto de referência</span><h3>${esc(point?.district||point?.neighborhood||study.municipality)}</h3><span class="tiny muted">${point?`Setor ${esc(point.code)} · ${esc(point.situation||'situação a confirmar')}`:'Ponto sem setor único identificado'}</span></div><span class="context-area-tag">Raio de seleção: ${num(local.selection.radiusM)} m</span></div><div class="context-indicators local-indicators"><div><span class="label">Moradores do setor</span><strong>${num(point?.population)} <small>pessoas</small></strong><span class="tiny muted">População residente · setor inteiro</span></div><div><span class="label">Densidade do setor</span><strong>${num(point?.densityHabKm2,2)} <small>hab/km²</small></strong><span class="tiny muted">Área do setor: ${num(point?.areaKm2,4)} km²</span></div><div><span class="label">Domicílios do setor</span><strong>${num(point?.households)}</strong><span class="tiny muted">Não equivale a demanda pelo produto</span></div></div><div class="context-charts"><div><h3>Densidade do entorno</h3><p class="tiny muted">${num(local.summary.sectorCount)} setores inteiros que intersectam o raio de ${num(local.selection.radiusM)} m, no mesmo município.</p><div id="context-density-chart" class="chart"></div></div><div><h3>Posição relativa do setor</h3><p class="tiny muted">Habitantes por km² · mesma edição censitária</p><div id="context-comparison-chart" class="chart"></div></div></div>`:''}<div class="context-municipal-title"><span class="label">Referência municipal · ${esc(study.municipality)}</span></div>${ind.length?`<div class="context-indicators municipal-indicators">${ind.map(i=>`<div><span class="label">${esc(i.label)}</span><strong>${num(i.value,i.unit==='hab/km²'?2:i.unit==='km²'?3:0)} <small>${esc(i.unit)}</small></strong><span class="tiny muted">${esc(i.referenceYear)} · município inteiro</span></div>`).join('')}</div>`:'<div class="card-body"><p class="small muted">Indicadores municipais aguardam consulta verificável.</p></div>'}<div class="context-local"><span class="label">Alcance da leitura</span><p>${hasLocal?'O ponto localiza um setor estatístico, não o domínio do imóvel. Os setores do entorno podem ultrapassar o raio selecionado. A leitura de mercado combina essa base com renda, oferta, absorção e acessibilidade.':esc(c?.localContext?.reason||'Vincular a malha censitária e os indicadores da mesma edição antes de qualificar o entorno.')}</p></div><details class="context-sources"><summary>Fontes, recorte e metodologia</summary>${hasLocal?`<p class="tiny">${esc(local.selection.method)} ${num(local.summary.fullyContainedSectorCount)} setores estão integralmente contidos. A soma dos setores inteiros (${num(local.summary.wholeSectorsPopulation)} moradores) não representa a população dentro do raio.</p>`:''}${[...(local?.sources||[]),...(c?.sources||[])].map(r=>`<p class="tiny">${r.url?`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title||r.id||r.url)}</a>`:esc(r.title||r.id)}${r.retrievedAt?' · consultada em '+dt(r.retrievedAt):''}${r.status?' · '+esc(r.status):''}</p>`).join('')||'<p class="tiny muted">Fontes serão registradas com a consulta.</p>'}${[...(local?.limitations||[]),...(c?.limitations||[])].map(l=>`<p class="tiny muted">${esc(l)}</p>`).join('')}</details></section>`;
}
function bindContext(){
 const local=study.localContext;if(local?.status!=='ok'||!local.sectors?.length)return;
 const histogram=densityHistogram(local.sectors,{breaks:study.geography?.layers?.find(l=>l.id==='censo2022')?.choropleth?.breaks}),point=local.sectors.find(s=>s.containsReferencePoint),municipal=study.context?.indicators?.find(i=>i.id==='density'&&i.referenceYear===local.referenceYear);
 chart('context-density-chart',{chart:{type:'bar',height:245},series:[{name:'Setores',data:histogram.map(b=>b.count)}],colors:['#c1cdbc','#91a589','#72896d','#536e50','#354e34','#d6d2c8'],plotOptions:{bar:{distributed:true,columnWidth:'48%',borderRadius:3}},legend:{show:false},xaxis:{categories:histogram.map(b=>b.label),labels:{rotate:0,style:{fontSize:'10px'}},title:{text:'Densidade · habitantes/km²',style:{fontSize:'10px',fontWeight:400}}},yaxis:{min:0,forceNiceScale:true,decimalsInFloat:0,labels:{formatter:v=>num(v)}},tooltip:{y:{formatter:v=>num(v)+' setores'}}});
 const rows=[{name:'Setor de referência',value:point?.densityHabKm2},{name:'Município',value:municipal?.value}].filter(r=>Number.isFinite(r.value));
 if(rows.length)chart('context-comparison-chart',{chart:{type:'bar',height:245},series:[{name:'Densidade',data:rows.map(r=>r.value)}],colors:['#9C745B','#91a589'],plotOptions:{bar:{horizontal:true,distributed:true,barHeight:'38%',borderRadius:3}},legend:{show:false},xaxis:{categories:rows.map(r=>r.name),labels:{formatter:v=>num(v)},title:{text:'Habitantes/km²',style:{fontSize:'10px',fontWeight:400}}},tooltip:{y:{formatter:v=>num(v,2)+' hab/km²'}}});
}
const verificationLabels={'divergente':'Divergência identificada','falha-temporaria':'Consulta temporariamente indisponível','sem-resultados-na-consulta':'Sem ocorrência no recorte','verificado-fonte':'Fonte verificada','indicio':'Indício identificado','encontrado':'Registro localizado','sem-cobertura':'Cobertura insuficiente','restrito':'Acesso restrito','dado-necessario':'Insumo necessário','nao-aplicavel':'Não aplicável','falha-consulta':'Consulta indisponível','pendente':'Pendente'};
function verificationSummary(){const v=study.verification;if(!v)return '<p class="small muted">Nenhuma execução registrada neste terreno.</p>';if(published)return `${renderVerificationFreshness(v)}<p class="small muted">${num(v.checks?.length||0)} verificações publicadas, com data, fonte e alcance próprios.</p>`;return `${renderVerificationFreshness(v)}<div class="verification-counts"><span><strong>${num(v.checks?.length||0)}</strong> verificações</span><span><strong>${num(v.summary?.userInputs||0)}</strong> insumos adicionais</span><span><strong>${num(v.summary?.specialist||0)}</strong> frentes técnicas</span></div><p class="tiny muted">Cobertura e indícios permanecem separados de aprovação do imóvel.</p>`;}
function verificationPanel(){return `<section class="card card-body verification-panel"><div class="row between wrap"><div><div class="eyebrow">Protocolo de verificação</div><h2 class="section-title">Primeiro, consultar e cruzar as bases</h2></div><button id="run-verification" class="primary">${study.verification?'Atualizar consultas':'Verificar bases acessíveis'}</button></div><p class="small muted">Consulta as fontes públicas conectadas, verifica geometria e acervo e guarda o resultado com data e alcance. A execução não consome créditos de APIs pagas.</p><div id="verification-output">${verificationResults()}</div></section>`;}
function verificationResults(){const v=study.verification;if(!v)return '<div class="note neutral">Inicie a consulta para separar o que já pode ser verificado, o que exige credencial e o que depende de documento ou campo.</div>';const rows=v.checks||[];return `${verificationSummary()}<div class="verification-filter"><label for="verification-owner">Mostrar</label><select id="verification-owner"><option value="all">Todas as verificações</option value="automacao">Consultas do sistema</option><option value="usuario">Insumos que dependem de você</option><option value="especialista">Verificação técnica</option></select><span class="tiny muted">Execução ${dt(v.at)}</span></div><div class="verification-list">${rows.map(r=>`<article class="verification-item" data-verification-owner="${esc(r.nextAction?.owner||'automacao')}"><div><h3>${esc(r.title)}</h3>${badge(verificationLabels[r.status]||r.status,['indicio','divergente'].includes(r.status)?'red':'gray')}</div><p>${esc(r.finding)}</p><p class="coverage"><strong>Alcance:</strong> ${esc(r.coverage||'Consultar recibo da execução.')}</p>${r.nextAction?`<p class="next-action"><strong>${r.nextAction.owner==='usuario'?'Insumo necessário':r.nextAction.owner==='especialista'?'Verificação técnica':'Próxima consulta'}:</strong> ${esc(r.nextAction.text)}</p>`:''}${r.source?`<details><summary>Fonte e rastreabilidade</summary><p class="tiny">${r.source.url?`<a href="${esc(r.source.url)}" target="_blank" rel="noopener noreferrer">${esc(r.source.title||r.source.url)}</a>`:esc(r.source.title||'Evidência local')} · ${dt(r.source.checkedAt||v.at)}${r.source.cached?' · captura reutilizada':''}</p>${r.source.sha256?`<p class="hash tiny">SHA-256 ${esc(r.source.sha256)}</p>`:''}</details>`:''}</article>`).join('')}</div>`;}
function bindVerification(){const button=$('#run-verification');if(!button)return;bindVerificationFilter();button.onclick=run(async()=>{const slug=study.slug;button.disabled=true;button.textContent='Consultando e cruzando bases…';try{const v=await api(endpoint('verification'),{});if(study.slug!==slug)return;study.verification=v;const fresh=await api(`/terreno/api/studies/${slug}`);if(study.slug!==slug)return;study.context=fresh.context;study.localContext=fresh.localContext;study.verification=fresh.verification||v;study.assessment=fresh.assessment;study.coherence=fresh.coherence;if($('#verification-output')){$('#verification-output').innerHTML=verificationResults();bindVerificationFilter();}toast('Verificação concluída. Consulte o alcance e as próximas ações de cada fonte.');}finally{if(document.contains(button)){button.disabled=false;button.textContent='Atualizar consultas';}}});}
function bindVerificationFilter(){if($('#verification-owner'))$('#verification-owner').onchange=e=>$$('[data-verification-owner]').forEach(row=>{row.hidden=e.target.value!=='all'&&row.dataset.verificationOwner!==e.target.value;});}

function layerMenu(){return `<details class="layer-dropdown"><summary>Camadas <span>⌄</span></summary><div class="layer-options"><p class="tiny muted">Ative as bases para confrontar com o perímetro.</p>${baseLayers(study).map(l=>`<label class="layer-option"><input type="checkbox" ${l.id==='relief'?'id="terrain-dem"':''} data-layer-group="${esc(l.layerIds.join(','))}" ${l.available?(l.default?'checked':''):'disabled'}><span><strong>${esc(l.label)}</strong><small>${esc(l.available?l.note:l.reason)}</small></span>${!l.available?'<span class="layer-pending">Pendente</span>':''}</label>`).join('')}<p class="tiny muted">Camada indisponível não significa ausência de restrição. Fontes e datas no protocolo.</p></div></details>`;}
function territory(){const g=study.geography;$('#content').innerHTML=`<div class="territory-pair"><section class="card map-card"><header class="card-head"><div class="row between wrap"><div><div class="eyebrow">Base territorial</div><h2 class="section-title">Mapa e condicionantes</h2></div><div class="row">${layerMenu()}<button id="fit-map" disabled aria-label="Enquadrar mapa">Enquadrar</button></div></div></header><div id="map" class="mapbox large"></div><div class="map-footer"><details><summary>Fonte do perímetro</summary><p>${esc(g.note)}</p></details></div></section>${volumePanel()}</div>${study.regulatory?`<div class="kpis">${kpi('Zona de referência',esc(study.regulatory.zone),'Enquadramento sujeito à confirmação aplicável')}${kpi('Envelope de ensaio',num(study.regulatory.envelopeAreaM2)+' m²',`Recuos de referência ${num(study.regulatory.setbackFrontM)} / ${num(study.regulatory.setbackOtherM)} m`)}${kpi('Altura de referência',num(study.regulatory.maxHeightM)+' m','Confrontar com restrições territoriais')}${kpi('Permeabilidade',num(study.regulatory.permeabilityPct)+'%','Área a compatibilizar na implantação')}</div><div class="note">${esc(study.regulatory.note)}</div>`:''}${renderSitePotential(study)}${renderLandReview(study,'territory')}${renderSubdivisionTerritory(study)}${contextPanel()}${climatePanel(study,{esc,num})}${study.subdivisionReview?'':`<section class="card card-body section-gap"><h2 class="section-title">Verificações territoriais</h2>${checkRows()}</section>`}`;
 potentialNavigation();bindLandReview(study,chart);bindSubdivisionCharts(study,chart,'territory');drawMap();bindVolume();bindContext();bindClimate(study,{chart});$('#fit-map').onclick=()=>map?.fit();$$('[data-layer-group]').forEach(el=>el.onchange=()=>{if(el.id==='terrain-dem')map?.setTerrain(el.checked);for(const id of el.dataset.layerGroup.split(',').filter(Boolean))map?.setLayer(id,el.checked);});}
function streetViewPanel(){return `<section id="streetview-section" class="card card-body section-gap"><header class="card-head" style="padding:0 0 18px"><div class="row between wrap"><div><div class="eyebrow">Vista ao nível da rua</div><h2 class="section-title">Fachada, acessos e entorno</h2><p>Comece próximo à frente do terreno e percorra os panoramas disponíveis.</p></div><div class="row wrap"><button id="street-review">Qualificar o entorno</button><button id="street-photo">Capturar foto própria</button></div></div></header><div id="streetview"></div><p class="tiny muted" style="margin-bottom:0">${esc(study.geography?.streetView?.source||'A consulta parte do ponto de referência; a correspondência com a fachada precisa de conferência.')} A vistoria reúne observações profissionais e fotos próprias, sem arquivar imagens do Google.</p></section>`;}
function openStreetView(){if(tab!=='field'){tab='field';render();}$('#streetview-section')?.scrollIntoView({behavior:'smooth',block:'start'});}
async function bindStreetView(){const host=$('#streetview');if(!host)return;const slug=study.slug;$('#street-review').onclick=()=>{const b=streetViewHandle?.getState?.().panoramasOpened>0?streetViewHandle.getBookmark?.():null;if(b)streetBookmark={heading:b.heading,pitch:b.pitch,fov:b.fov};$('#surroundings-section')?.scrollIntoView({block:'start'});};$('#street-photo').onclick=()=>$('#surround-photo')?.click();try{const instance=await mountStreetView(host,study);if(study.slug!==slug||host!==$('#streetview'))instance?.destroy();else streetViewHandle=instance;}catch{if(host===$('#streetview'))host.innerHTML='<p class="small muted">A vista de rua não pôde ser iniciada. Tente novamente ou utilize o link de referência na vistoria.</p>';}}
function exploratoryControls(){const p=study.geography.exploratoryProposal;return `<div class="physical-controls"><div class="eyebrow">Ensaio de produto · implantação a qualificar</div><div class="floors-row"><div class="param"><header><label for="exploratory-floors">Pavimentos gráficos</label><input type="number" id="exploratory-floors" min="1" max="3" step="1" value="${volume.floors}"></header><input type="range" id="exploratory-floors-range" min="1" max="3" value="${volume.floors}" aria-label="Ajustar pavimentos gráficos"></div><div id="exploratory-summary"></div></div><p class="tiny muted">3 m por pavimento · intervalo do simulador, sem limite legal de altura adotado.</p><details class="small"><summary>Condições da implantação</summary><p>${esc(p.description||p.label)}</p><ul>${(p.prerequisites??[]).map(x=>`<li>${esc(typeof x==='string'?x:x.label||x.description||JSON.stringify(x))}</li>`).join('')}</ul><p>O ensaio não adota área aproveitável nem altera o fluxo financeiro.</p></details></div>`;}
function initExploratoryControls(){const p=study.geography.exploratoryProposal;function update(){const floors=Number($('#exploratory-floors').value);if(!Number.isInteger(floors)||floors<1||floors>3)return;volume={floors,floorHeightM:3};$('#exploratory-floors-range').value=floors;$('#exploratory-summary').innerHTML=`<strong>${num(p.footprintM2)} m² de pegada</strong><span>${floors} pavimento(s) gráfico(s) · ${floors*3} m</span>`;volumeView?.setScenario?.({floors});}$('#exploratory-floors').oninput=update;$('#exploratory-floors-range').oninput=e=>{$('#exploratory-floors').value=e.target.value;update();};update();}
function physicalControls(){return `<div class="physical-controls"><div class="floors-row"><div class="param"><header><label for="volume-floors">Pavimentos do ensaio</label><input type="number" id="volume-floors" min="1" max="12" step="1" value="${volume.floors}"></header><input type="range" id="volume-floors-range" min="1" max="12" step="1" value="${volume.floors}" aria-label="Ajustar pavimentos do ensaio"></div><div id="volume-summary"></div></div><div id="volume-warning" class="volume-note"></div><div class="row between wrap"><span class="tiny muted">3 m por pavimento · inclui térreo</span><button id="apply-volume" class="primary">Testar área no produto principal</button></div><details class="tiny muted"><summary>Premissas geométricas</summary><p>${num(study.regulatory.footprintM2)} m² de projeções de ensaio. Área bruta empilhada não equivale à computável nem comprova número de unidades. Áreas técnicas, núcleo, permeabilidade e acessos exigem compatibilização.</p></details></div>`;}
function initPhysicalControls(){if(!$('#volume-floors'))return;function update(){const floors=Number($('#volume-floors').value);if(!Number.isInteger(floors)||floors<1||floors>12){$('#apply-volume').disabled=true;$('#volume-warning').textContent='Informe de 1 a 12 pavimentos para este ensaio.';return;}volume={floors,floorHeightM:3};const h=floors*3,area=study.regulatory.footprintM2*floors,over=h>study.regulatory.maxHeightM;$('#volume-floors-range').value=floors;$('#volume-summary').innerHTML=`<strong>${num(area)} m²</strong><span>${num(floors)} pavimentos · ${num(h)} m de altura</span>`;$('#volume-warning').className='volume-note '+(over?'alert':'');$('#volume-warning').textContent=over?`${num(h)} m supera a referência de ${num(study.regulatory.maxHeightM)} m. Ajuste o ensaio antes de aplicar.`:`Referência de altura: ${num(study.regulatory.maxHeightM)} m. Demais restrições permanecem condicionantes.`;$('#apply-volume').disabled=over||!primaryPreset();volumeView?.setScenario?.({floors});}
 $('#volume-floors').oninput=update;$('#volume-floors-range').oninput=e=>{$('#volume-floors').value=e.target.value;update();};$('#apply-volume').onclick=()=>{const p=primaryPreset();if(!p)return;if(activePreset?.id!==p.id){activePreset=p;changes={...p.controls};}changes.built_area_m2=study.regulatory.footprintM2*volume.floors;tab='scenarios';render();toast('Área bruta aplicada ao produto principal. Confira eficiência, custos e condições.');};update();}

