 if(ch?.sales_units)chart('absorption-chart',{chart:{type:'line',height:270},series:[{name:'Vendas do mês',type:'column',data:ch.sales_units},{name:'Vendas acumuladas',type:'line',data:ch.cumulative_sales_units}],colors:['#8ca486','#9c745b'],stroke:{width:[0,2.5]},plotOptions:{bar:{columnWidth:'70%'}},xaxis:{categories:ch.month_indices.map(v=>'M'+v),tickAmount:5},yaxis:[{seriesName:'Vendas do mês',title:{text:'Unidades / mês',style:{fontSize:'10px'}},labels:{formatter:v=>num(v,1)}},{seriesName:'Vendas acumuladas',opposite:true,title:{text:'Acumulado',style:{fontSize:'10px'}},labels:{formatter:v=>num(v)}}],tooltip:{y:{formatter:v=>num(v,1)+' un.'}}});else $('#absorption-chart').innerHTML='<p class="card-body small muted">Este cenário legado contém recebimentos agregados. Selecione o estudo por coortes para modular vendas e estoque.</p>';
